# Created by OpenAI
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

@gluon.jit
def _slot_tile(Slots, row, split, x, TOPK: gl.constexpr, KEYS: gl.constexpr, LINEAR: gl.constexpr=False):
    index = split * KEYS + x
    if LINEAR:
        pointers = Slots + row * TOPK + index
    else:
        pointers = Slots + row * TOPK + split * KEYS + x
    if TOPK % KEYS == 0:
        return gl.load(pointers)
    return gl.load(pointers, index < TOPK, -1)

@gluon.constexpr_function
def _mfma_layout(warps, reduction):
    return gl.amd.AMDMFMALayout(4, [16, 16, reduction], True, [1, warps])

@gluon.jit
def _read_fp8(tile, OP: gl.constexpr, MFMA: gl.constexpr, PACK: gl.constexpr, RELAXED: gl.constexpr=True):
    layout: gl.constexpr = gl.DotOperandLayout(OP, MFMA, PACK)
    if RELAXED:
        bits = gl.amd.cdna4.async_copy.load_shared_relaxed(tile, layout)
    else:
        bits = tile.load(layout)
    return bits.to(gl.float8e4nv, bitcast=True)

@gluon.jit
def _softmax_weights(score, valid, AXIS: gl.constexpr):
    score = gl.where(valid, score, -float('inf'))
    maximum = gl.max(score, AXIS)
    safe = gl.where(maximum == -float('inf'), 0.0, maximum)
    shifted = score - (safe[:, None] if AXIS == 1 else safe)
    return (maximum, gl.where(valid, gl.exp2(shifted * 1.4426950408889634), 0.0))

@gluon.constexpr_function
def _panel_layout(keys, panel):
    bases = [[0, 1 << i] for i in range(6)]
    bases += [[1 << i, 0] for i in range(keys.bit_length() - 1)]
    bases += [[0, 1 << i] for i in range(6, panel.bit_length() - 1)]
    return gl.SharedLinearLayout(bases, alignment=16)

@gluon.jit
def _start_panels(values, KV, offset, kd, valid, S: gl.constexpr):
    for i in gl.static_range(512 // S.qk_panel):
        offs = gl.max_contiguous(offset[:, None] + i * S.qk_panel + kd[None, :], [1, 16])
        if S.zero_fill:
            gl.amd.cdna4.async_copy.buffer_load_to_shared(values[i], KV, offs, gl.full((offs.shape[0], offs.shape[1]), True, gl.int1, offs.type.layout))
        else:
            gl.amd.cdna4.async_copy.buffer_load_to_shared(values[i], KV, offs, valid[:, None])
        gl.amd.cdna4.async_copy.commit_group()

@gluon.jit
def _panel_qk(qs, qrs, krs, values, S: gl.constexpr):
    HT: gl.constexpr = 8
    qkl: gl.constexpr = _mfma_layout(S.warps, 128)
    pvl: gl.constexpr = _mfma_layout(S.warps, 32)
    qra = _read_fp8(qrs, 0, pvl, 8)
    krb = _read_fp8(krs.permute((1, 0)), 1, pvl, 8)
    rope_score = gl.amd.cdna4.mfma(qra, krb, gl.zeros((HT, S.keys), gl.float32, pvl))
    if S.rope_first:
        score = gl.convert_layout(rope_score, qkl)
    else:
        score = gl.zeros((HT, S.keys), gl.float32, qkl)
    for i in gl.static_range(512 // S.qk_panel):
        qa = _read_fp8(qs.slice(i * S.qk_panel, S.qk_panel, 1), 0, qkl, 32)
        gl.amd.cdna4.async_copy.wait_group(512 // S.qk_panel - i - 1)
        kb = _read_fp8(values[i].permute((1, 0)), 1, qkl, 32)
        score = gl.amd.cdna4.mfma_scaled(qa, None, 'e4m3', kb, None, 'e4m3', score)
    if not S.rope_first:
        score = score + gl.convert_layout(rope_score, qkl)
    return score

@gluon.jit
def _vector_partials(Q, KV, Slots, Part, Stats, HEADS: gl.constexpr, TOPK: gl.constexpr, SCALE: gl.constexpr, KEYS: gl.constexpr, SPLITS: gl.constexpr, QUANTIZE: gl.constexpr):
    row, head, split = (gl.program_id(0), gl.program_id(1), gl.program_id(2))
    layout: gl.constexpr = gl.BlockedLayout([1, 4], [4, 16], [4, 1], [1, 0])
    x = gl.arange(0, KEYS, layout=gl.SliceLayout(1, layout))
    d = gl.arange(0, 512, layout=gl.SliceLayout(0, layout))
    r = gl.arange(0, 64, layout=gl.SliceLayout(0, layout))
    slot = _slot_tile(Slots, row, split, x, TOPK, KEYS)
    valid = slot >= 0
    offset = gl.maximum(slot, 0).to(gl.int64) * 576
    q = gl.load(Q + (row * HEADS + head) * 576 + d)
    qr = gl.load(Q + (row * HEADS + head) * 576 + 512 + r)
    if QUANTIZE:
        q = q.to(gl.float8e4nv)
        qr = qr.to(gl.float8e4nv)
    q, qr = (q.to(gl.float32), qr.to(gl.float32))
    v = gl.load(KV + offset[:, None] + d[None, :], valid[:, None], 0.0).to(gl.float32)
    kr = gl.load(KV + offset[:, None] + 512 + r[None, :], valid[:, None], 0.0).to(gl.float32)
    score = (gl.sum(v * q[None, :], 1) + gl.sum(kr * qr[None, :], 1)) * SCALE
    maximum, p = _softmax_weights(score, valid, 0)
    numer, denom = (gl.sum(p[:, None] * v, 0), gl.sum(p, 0))
    record = (row * SPLITS + split) * HEADS + head
    gl.store(Part + record * 512 + d, numer)
    sm = (row * HEADS + head) * SPLITS + split
    gl.store(Stats + sm * 2, maximum)
    gl.store(Stats + sm * 2 + 1, denom)

@gluon.jit
def _merge(Part, Stats, Out, HEADS: gl.constexpr, SPLITS: gl.constexpr, RS: gl.constexpr, VALUE_BLOCK: gl.constexpr, PITCH: gl.constexpr, VECTOR: gl.constexpr=4):
    row, head, tile = (gl.program_id(0), gl.program_id(1), gl.program_id(2))
    LANES: gl.constexpr = VALUE_BLOCK // VECTOR
    layout: gl.constexpr = gl.BlockedLayout([1, VECTOR], [64 // LANES, LANES], [1, 1], [1, 0])
    s = gl.arange(0, RS, layout=gl.SliceLayout(1, layout))
    d = tile * VALUE_BLOCK + gl.arange(0, VALUE_BLOCK, layout=gl.SliceLayout(0, layout))
    rec = (row * HEADS + head) * SPLITS + s
    maxima = gl.load(Stats + rec * 2, s < SPLITS, -float('inf'))
    sums = gl.load(Stats + rec * 2 + 1, s < SPLITS, 0.0)
    maximum = gl.max(maxima, 0)
    safe = gl.where(maximum == -float('inf'), 0.0, maximum)
    weight = gl.exp2((maxima - safe) * 1.4426950408889634)
    total = gl.sum(weight * sums, 0)
    part_rec = (row * SPLITS + s) * HEADS + head
    parts = gl.load(Part + part_rec[:, None] * PITCH + d[None, :], s[:, None] < SPLITS, 0.0).to(gl.float32)
    inverse = 1.0 / gl.where(total > 0.0, total, 1.0)
    result = gl.sum(parts * weight[:, None], 0) * inverse
    gl.store(Out + (row * HEADS + head) * 512 + d, result)

def _supports_buffer_copy(cache):
    offset = cache.storage_offset()
    return offset % 16 == 0 and (offset + cache.numel()) * cache.element_size() < 2 ** 31 - 2
